		foreach( $name in $names ) {
		  reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager" /v $name /t REG_DWORD /d 0 /f;
		}
	};
	{
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" /v TaskbarAl /t REG_DWORD /d 0 /f;
	};
	{
		$params = @{
		  LiteralPath = 'Registry::HKU\DefaultUser\Control Panel\Mouse';
		  Type = 'String';
		  Value = 0;
		  Force = $true;
		};
		Set-ItemProperty @params -Name 'MouseSpeed';
		Set-ItemProperty @params -Name 'MouseThreshold1';
		Set-ItemProperty @params -Name 'MouseThreshold2';
	};
	{
		reg.exe add "HKU\DefaultUser\Control Panel\Accessibility\StickyKeys" /v Flags /t REG_SZ /d 10 /f;
	};
	{
		# Screen saver off, no password on resume, for every account
		# created from here on. The tune-windows setup step writes the
		# same values to HKCU, but setup steps run as the agent service
		# (SYSTEM) now, whose HKCU is not the user's.
		reg.exe add "HKU\DefaultUser\Control Panel\Desktop" /v ScreenSaveActive /t REG_SZ /d 0 /f;
		reg.exe add "HKU\DefaultUser\Control Panel\Desktop" /v ScreenSaverIsSecure /t REG_SZ /d 0 /f;
		reg.exe add "HKU\DefaultUser\Control Panel\Desktop" /v ScreenSaveTimeOut /t REG_SZ /d 0 /f;
	};
	{
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\RunOnce" /v "UnattendedSetup" /t REG_SZ /d "powershell.exe -WindowStyle \""Normal\"" -ExecutionPolicy \""Unrestricted\"" -NoProfile -File \""C:\Windows\Setup\Scripts\UserOnce.ps1\""" /f;
	};
);

& {
  [float] $complete = 0;
  [float] $increment = 100 / $scripts.Count;
  foreach( $script in $scripts ) {
    Write-Progress -Id 0 -Activity 'Running scripts to modify the default user’’s registry hive. Do not close this window.' -PercentComplete $complete;
    '*** Will now execute command «{0}».' -f $(
      $script.ToString().Trim() -replace '\s+', ' ' -replace '^(.{99})(.+)$', '$1…';
    );
    $start = [datetime]::Now;
    & $script;
    '*** Finished executing command after {0:0} ms.' -f [datetime]::Now.Subtract( $start ).TotalMilliseconds;
    "`r`n" * 3;
    $complete += $increment;
  }
} *>&1 | Out-String -Width 1KB -Stream >> "C:\Windows\Setup\Scripts\DefaultUser.log";

$scripts = @(
	{
		Remove-Item -LiteralPath @(
		  'C:\Windows\Panther\unattend.xml';
		  'C:\Windows\Panther\unattend-original.xml';
		  'C:\Windows\Setup\Scripts\Wifi.xml';
		) -Force -ErrorAction 'SilentlyContinue' -Verbose;
	};
	{
		# Marker that the finalize scripts ran to completion. Useful
		# for diagnosing a half-finished install; nothing gates on it.
		#
		# It is NOT an OOBE-done sentinel and must not be used as one:
		# FirstLogonCommands is part of OOBE and runs while the
		# "Preparing Windows" screen is still displayed, so this file
		# appears well before there is a desktop. The agent decides
		# for itself when the session is usable by waiting on the
		# shell (see win::DesktopSession).
		New-Item -ItemType Directory -Force -Path 'C:\ProgramData\LSW' | Out-Null;
		Set-Content -LiteralPath 'C:\ProgramData\LSW\lsw-ready.flag' -Value (Get-Date -Format s) -Encoding Ascii -Force;
	};
);

& {
  [float] $complete = 0;
  [float] $increment = 100 / $scripts.Count;
  foreach( $script in $scripts ) {
    Write-Progress -Id 0 -Activity 'Running scripts to finalize your Windows installation. Do not close this window.' -PercentComplete $complete;
    '*** Will now execute command «{0}».' -f $(
      $script.ToString().Trim() -replace '\s+', ' ' -replace '^(.{99})(.+)$', '$1…';
    );
    $start = [datetime]::Now;
    & $script;
    '*** Finished executing command after {0:0} ms.' -f [datetime]::Now.Subtract( $start ).TotalMilliseconds;
    "`r`n" * 3;
    $complete += $increment;
  }
} *>&1 | Out-String -Width 1KB -Stream >> "C:\Windows\Setup\Scripts\FirstLogon.log";

$ErrorActionPreference = 'Continue';
New-Item -ItemType Directory -Force -Path 'C:\ProgramData\LSW' | Out-Null;
$log = 'C:\ProgramData\LSW\av-sign.log';
function L($m) { ('{0} {1}' -f (Get-Date -Format s), $m) | Add-Content -LiteralPath $log -Encoding Ascii; }
$avScript = 'C:\av\provision.ps1';
if (-not (Test-Path -LiteralPath $avScript)) { L ($avScript + ' missing - the payload carried no driver package'); exit 0; }
L ('sign start; ctx=' + [System.Security.Principal.WindowsIdentity]::GetCurrent().Name);
$out = & powershell.exe -NoProfile -ExecutionPolicy Bypass -File $avScript -Stage sign 2>&1 | Out-String;
$rc = $LASTEXITCODE;
if ($out) { $out.TrimEnd() | Add-Content -LiteralPath $log -Encoding Ascii; }
# 3010 is provision.ps1 asking for the reboot specialize ends with anyway.
if ($rc -eq 0 -or $rc -eq 3010) { L ('provision.ps1 -Stage sign exited ' + $rc + ' - signed'); }
else { L ('provision.ps1 -Stage sign exited ' + $rc + ' - FAILED; LswPromote.ps1 tries again'); }
exit 0;

$ErrorActionPreference = 'Continue';
New-Item -ItemType Directory -Force -Path 'C:\ProgramData\LSW' | Out-Null;
$log = 'C:\ProgramData\LSW\promote.log';
function L($m) { ('{0} {1}' -f (Get-Date -Format s), $m) | Add-Content -LiteralPath $log -Encoding Ascii; }
# The accel-virt display driver, first: it needs nothing from the
# account below, and the promotion has exits this must not sit behind.
#
# Specialize signed the package (LswAvSign.ps1, av-sign.log) and turned
# test signing on, and the reboot that ended specialize put it in force;
# what is left is the install stage, which is here because pnputil and
# the PnP stack want a fully booted Windows. As SYSTEM because it writes
# the driver store and GraphicsDrivers. The av device is present in this
# boot - the install-time domain has it beside the VGA adapter - so
# pnputil installs onto it and avgpu.sys can start straight away; the
# VGA adapter stays the display until the manager restarts the VM into
# its steady-state shape once setup is done.
#
# Sign again only when the catalog is missing or not validly signed,
# i.e. when specialize's sign did not finish: sign is not re-runnable
# over its own output, because it first checks every file against
# package.sha256 and its first run rewrote avgpu.inf and signed
# avgpu.sys. A sign that has to happen here leaves test signing for the
# next boot, which the retry task below then covers.
#
# Test signing is only possible because Secure Boot has no keys here
# (OVMF_CODE.4m.fd, OVMF_VARS.4m.fd): with keys enrolled, bcdedit
# refuses testsigning outright.
$avFlag = 'C:\ProgramData\LSW\av-installed.flag';
$avScript = 'C:\av\provision.ps1';
$avCatalog = 'C:\av\package\avgpu.cat';
$avRetryTask = 'lsw-av-install';
function AvStage([string[]] $stageArgs) {
    $out = & powershell.exe -NoProfile -ExecutionPolicy Bypass -File $avScript @stageArgs 2>&1 | Out-String;
    $rc = $LASTEXITCODE;
    if ($out) { $out.TrimEnd() | Add-Content -LiteralPath $log -Encoding Ascii; }
    L ('provision.ps1 ' + ($stageArgs -join ' ') + ' exited ' + $rc);
    # 3010 is provision.ps1 asking for a reboot, not a failure.
    return ($rc -eq 0 -or $rc -eq 3010);
}
function AvSigned {
    if (-not (Test-Path -LiteralPath $avCatalog)) { return $false; }
    return ((Get-AuthenticodeSignature -LiteralPath $avCatalog).Status -eq 'Valid');
}
if (Test-Path -LiteralPath $avFlag) {
    L 'av-installed.flag present - driver already installed';
} elseif (-not (Test-Path -LiteralPath $avScript)) {
    L ($avScript + ' missing - the payload carried no driver package');
} else {
    L ('test signing: ' + ((bcdedit.exe /enum '{current}' | Select-String -Pattern 'testsigning') -join ' '));
    $avOk = $true;
    if (-not (AvSigned)) {
        L ($avCatalog + ' missing or unsigned - specialize did not sign (see av-sign.log); signing here');
        $avOk = AvStage @('-Stage', 'sign');
    }
    if ($avOk -and (AvStage @('-Stage', 'install', '-NoVerifier'))) {
        Set-Content -LiteralPath $avFlag -Value (Get-Date -Format s) -Encoding Ascii -Force;
        schtasks.exe /Delete /TN $avRetryTask /F 2>&1 | Out-Null;
        L 'accel-virt driver installed';
    } else {
        # Tried again at every boot, as SYSTEM, until it takes: this
        # whole script is the retry, since the driver block runs ahead of
        # the promotion's flag and the success above deletes the task.
        schtasks.exe /Create /TN $avRetryTask /RU SYSTEM /SC ONSTART /RL HIGHEST /F /TR 'powershell.exe -NoProfile -ExecutionPolicy Bypass -File C:\Windows\Setup\Scripts\LswPromote.ps1' 2>&1 | Out-Null;
        L ('accel-virt driver install FAILED - see provision.ps1 output above; retrying at boot (task ' + $avRetryTask + ')');
    }
}
# The loaders the driver's ICDs are found through. Windows ships no
# OpenCL.dll and, depending on the build, no vulkan-1.dll; one it does
# ship is kept, because it serves the whole machine and may be newer
# than ours. Machine-wide on purpose: a loader is not per-application.
# A 32-bit process looks in SysWOW64, so the x86 pair goes there.
foreach ($target in @(@('x64', 'System32'), @('x86', 'SysWOW64'))) {
    foreach ($dll in @('vulkan-1.dll', 'OpenCL.dll')) {
        $src = 'C:\av\loaders\' + $target[0] + '\' + $dll;
        $dst = $env:windir + '\' + $target[1] + '\' + $dll;
        if (-not (Test-Path -LiteralPath $src)) { continue; }
        if (Test-Path -LiteralPath $dst) { L ($dst + ' already present - kept'); continue; }
        try {
            Copy-Item -LiteralPath $src -Destination $dst -Force -ErrorAction Stop;
            L ('installed ' + $dst);
        } catch {
            L ('installing ' + $dst + ' FAILED: ' + $_.Exception.Message);
        }
    }
}
# The guest agent: the 'lsw-agent' Windows service. LocalSystem, in
# session 0, automatic start; the SCM restarts it if it fails (after 5 s,
# 5 s, then 30 s; the count resets after a day), and failureflag makes a
# non-zero exit count as a failure too - which is how the agent reports
# a port it could not bind. Here, at SetupComplete, and not in
# specialize: it first runs after OOBE, so its install gate (port 5102
# stays closed until a helper in the wizard user's session sees a usable
# desktop) never meets OOBE's own sessions. Ahead of the promotion below, which has early exits; a
# service needs no account. Idempotent, because SetupComplete can run
# twice: an existing service is reconfigured, and starting a running one
# is a harmless error.
$svc = 'lsw-agent';
$svcBin = 'C:\ProgramData\LSW\lsw-agent.exe --service';
if (Get-Service -Name $svc -ErrorAction SilentlyContinue) {
    $out = sc.exe config $svc binPath= $svcBin start= auto obj= LocalSystem 2>&1 | Out-String;
} else {
    $out = sc.exe create $svc binPath= $svcBin start= auto obj= LocalSystem DisplayName= 'LSW Guest Agent' 2>&1 | Out-String;
}
L ('lsw-agent service: ' + $out.Trim());
sc.exe description $svc 'The LSW manager''s control channel into this VM.' 2>&1 | Out-Null;
$out = sc.exe failure $svc reset= 86400 actions= restart/5000/restart/5000/restart/30000 2>&1 | Out-String;
L ('lsw-agent recovery: ' + $out.Trim());
sc.exe failureflag $svc 1 2>&1 | Out-Null;
$out = sc.exe start $svc 2>&1 | Out-String;
L ('lsw-agent start: ' + $out.Trim());
$flag = 'C:\ProgramData\LSW\promoted.flag';
# SetupComplete.cmd can run twice on Win11 (SYSTEM during setup, then
# again post first-logon); the sentinel makes the second run a no-op.
if (Test-Path -LiteralPath $flag) { L 'promoted.flag present - skipping'; exit 0; }
$u = '{{user_name}}';
L ('SetupComplete promote start; target=' + $u + '; ctx=' + [System.Security.Principal.WindowsIdentity]::GetCurrent().Name);
# The account is created in the oobeSystem pass; SetupComplete normally
# runs after that, but guard the race with a bounded wait so we never
# deadlock OOBE (give up after ~5 min, exit 0).
$lu = $null; $n = 0;
while ($n -lt 60) {
    $lu = Get-LocalUser -Name $u -ErrorAction SilentlyContinue;
    if ($lu) { break; }
    Start-Sleep -Seconds 5; $n++;
}
if (-not $lu) { L 'account never materialized after 5 min - giving up'; exit 0; }
$members = @( Get-LocalGroupMember -Group 'Administrators' -ErrorAction SilentlyContinue | ForEach-Object { $_.SID.Value } );
if ($members -contains $lu.SID.Value) {
    L ('already a member: ' + $u);
} else {
    try {
        Add-LocalGroupMember -Group 'Administrators' -Member $lu -ErrorAction Stop;
        L ('ADDED ' + $u + ' to local Administrators');
    } catch {
        L ('Add-LocalGroupMember FAILED: ' + $_.Exception.Message);
        exit 0;
    }
}
Set-Content -LiteralPath $flag -Value (Get-Date -Format s) -Encoding Ascii -Force;
( Get-LocalGroupMember -Group 'Administrators' | Format-Table Name, SID -AutoSize | Out-String ) | Add-Content -LiteralPath $log -Encoding Ascii;
L 'SetupComplete promote done';
